options.getOption:
let result = [];
let total = 0;

context.panel.data.series.forEach((s) => {
  console.log(s)
  if (s.refId === 'B') {
    timeData = s.fields.find(f => f.name === 'Time')?.values ?? [];
    result = s.fields.find(f => f.name === 'B')?.values ?? [];
    total = result.reduce((sum, value) => sum + Number(value), 0);
  }
});
const countOfValidValues = result.filter(v => v !== null && v !== undefined).length;

const seriesType = countOfValidValues > 1 ? 'line' : 'scatter';

if (!total) {
  return {
    title: {
      text: 'No data',
      left: 'center',
      top: 'middle',
      textStyle: {
        fontSize: 18,
        color: 'rgba(204, 204, 220, 0.65)',
        fontWeight: 400,
        fontFamily: 'Inter'
      }
    }
  };
}


const formattedDates = timeData.map((d, i) => {
  const value = result[i];

  if (value === null || value === undefined) {
    // Force time to 00:00:00 in IST
    const date = new Date(d);
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${month}/${day}/${year} 00:00:00`;
  } else {
    // Keep real timestamp with local conversion
    return new Intl.DateTimeFormat("en-US", {
      timeZone: "Asia/Kolkata",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
    }).format(new Date(d));
  }
});


return {
  tooltip: {
    trigger: 'axis',
    axisPointer: {
      type: 'cross'
    },
    formatter: function (params) {
      if (!params || !params.length) return '';
      const point = params[0];
      if (point.data === null || point.data === undefined || point.data === '') {
        return '';
      }
      const dateStr = point.axisValueLabel;
      const value = point.data;
      return `${dateStr}<br/>${point.seriesName}: ${value}`;
    }
  },
  legend: {
    data: ['COD(mg/l)']
  },
  grid: {
    left: '5%',
    right: '4%',
    bottom: '10%',
    containLabel: true
  },
  xAxis: {
    type: 'category',
    data: formattedDates,
    axisLabel: {
      formatter: function (val) {
        const date = new Date(val);
        const month = date.getMonth() + 1; // Month is zero-indexed
        const day = date.getDate();
        return `${month}/${day}`;
      }
    }
  },
  yAxis: {
    type: 'value',
  },
  series: [
    {
      name: 'COD(mg/l)',
      type: seriesType,
      data: result,
      connectNulls: true,
      color: "#73BF69",
      symbolSize: 5,
      showSymbol: true,
      emphasis: {
        focus: 'series'          // optional: highlight full series on hover
      }
    }
  ]

};

